message.content:
{
  "definition_simple": "話やパーティーなどが、とてもにぎやかで楽しくなること。",
  "definition_standard": "雰囲気や気分、議論などが高まって活気や熱気を帯びること。",
  "pos": "動詞（五段活用・自動詞）",
  "semantic_class": "action",
  "sentences": [
    {
      "tier": "T1",
      "text": "パーティーはとても盛り上がった。",
      "translation": "The party got very lively."
    },
    {
      "tier": "T2",
      "text": "友達と好きな音楽の話で盛り上がる。",
      "translation": "I get excited talking with my friends about music we like."
    },
    {
      "tier": "T2",
      "text": "みんなでカラオケに行き、大いに盛り上がった。",
      "translation": "We all went to karaoke and had a fantastic, lively time."
    },
    {
      "tier": "T3",
      "text": "試合の終盤、スタジアム全体の熱気が一気に盛り上がった。",
      "translation": "Near the end of the match, the enthusiasm throughout the entire stadium surged at once."
    },
    {
      "tier": "T3",
      "text": "最初は静かだったが、お酒が入ると徐々に場が盛り上がってきた。",
      "translation": "It was quiet at first, but as drinks flowed, the mood of the room gradually became lively."
    },
    {
      "tier": "T4",
      "text": "観客の手拍子とともに、会場のボルテージは最高潮に盛り上がった。",
      "translation": "Along with the clapping of the audience, the voltage of the venue rose to its climax."
    },
    {
      "tier": "T4",
      "text": "選挙戦が佳境に入り、支持者たちの間で議論が盛り上がりを見せている。",
      "translation": "As the election campaign enters its final stretch, discussions among supporters are heating up."
    },
    {
      "tier": "T5",
      "text": "世論の反対運動が盛り上がるにつれて、政府も方針の再検討を迫られた。",
      "translation": "As the public opposition movement gathered momentum, the government was forced to reconsider its policy."
    },
    {
      "tier": "T5",
      "text": "地域の祭りは、若者たちの熱心な参加によって再び盛り上がりを取り戻した。",
      "translation": "The local festival regained its liveliness thanks to the enthusiastic participation of the youth."
    },
    {
      "tier": "T6",
      "text": "国際情勢の緊迫化に伴い、安全保障を巡る国民的な議論がかつてないほど盛り上がりを見せている。",
      "translation": "With international tensions mounting, nationwide debate over national security is building up to unprecedented levels."
    }
  ],
  "morphological_forms": [
    {
      "label": "past_tense",
      "form": "盛り上がった"
    },
    {
      "label": "polite_negative",
      "form": "盛り上がりません"
    },
    {
      "label": "te_form",
      "form": "盛り上がって"
    }
  ],
  "morphology_wrong_forms": [
    {
      "label": "past_tense",
      "wrong_forms": [
        {
          "form": "盛り上がりた",
          "explanation": "一段動詞（る動詞）と混同して、五段動詞の促音便変化（った）を行わずに連用形に直接「た」を接続している。"
        },
        {
          "form": "盛り上った",
          "explanation": "活用語尾の送り仮名「が」を脱落させて表記している。"
        },
        {
          "form": "盛り上がした",
          "explanation": "サ変動詞の過去形「〜した」と混同して、誤った助動詞接続を作っている。"
        }
      ]
    },
    {
      "label": "polite_negative",
      "wrong_forms": [
        {
          "form": "盛り上がらません",
          "explanation": "連用形接続である「ません」を、未然形語幹「〜ら」に誤って接続している。"
        },
        {
          "form": "盛り上げません",
          "explanation": "他動詞「盛り上げる」の一段活用と混同し、自動詞の丁寧否定として誤った語幹を用いている。"
        },
        {
          "form": "盛り上がりくないです",
          "explanation": "動詞の活用であるにもかかわらず、形容詞の否定形規則（〜くない）を混同して適用している。"
        }
      ]
    },
    {
      "label": "te_form",
      "wrong_forms": [
        {
          "form": "盛り上がりて",
          "explanation": "ラ行五段活用の促音便（って）を作らず、古語や一段動詞のように連用形にそのまま「て」を付けている。"
        },
        {
          "form": "盛り上がいで",
          "explanation": "「泳ぐ→泳いで」などのガ行イ音便と混同し、ラ行活用の動詞に濁音便「いで」を誤用している。"
        },
        {
          "form": "盛り上がってて",
          "explanation": "促音便化した接続形に不要な接続助詞「て」を重複して重ねている。"
        }
      ]
    }
  ],
  "primary_collocate": "場が盛り上がる",
  "collocation_distractors": [
    {
      "word": "気温が盛り上がる",
      "explanation": "温度の上昇には単に「上がる」を用い、熱気や活気の高まりを表す「盛り上がる」は共起しない。"
    },
    {
      "word": "声が盛り上がる",
      "explanation": "声の音量や調子には「大きくなる」や「張り上がる」を用い、「盛り上がる」は使わない。"
    },
    {
      "word": "値段が盛り上がる",
      "explanation": "物価や金額の高騰には「上がる」や「高騰する」を用い、感情や場の熱狂を表す「盛り上がる」は不適切である。"
    }
  ],
  "collocation_wrong_collocate": "天気が盛り上がる",
  "cloze_distractors": [
    {
      "word": "増大した",
      "explanation": "「増大する」は数量や規模・程度が客観的に増える際に用いるため、パーティーの活況を表す文脈には不自然である。"
    },
    {
      "word": "浮かれた",
      "explanation": "「浮かれる」は個人が軽薄に陽気な気分になることを指し、集まり全体の熱気や楽しさを表す語として適さない。"
    },
    {
      "word": "登った",
      "explanation": "「登る」は物理的に高い場所へと移動する動作を表し、場の雰囲気や感情の昂揚には一切使用できない。"
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "司会者は会場の観客を大いに盛り上がった。",
      "reason": "「盛り上がる」は自動詞であるため、「〜を盛り上がる」のように目的語を取ることはできず、他動詞「盛り上げる」を用いる必要がある。"
    },
    {
      "sentence": "お風呂を沸かしたら、お湯の温度が急速に盛り上がった。",
      "reason": "「盛り上がる」は雰囲気や議論の熱気の高まりに使われる語であり、物理的な温度の上昇には「上がる」を用いるべきである。"
    },
    {
      "sentence": "彼は毎日の筋トレで筋肉の力を盛り上がっている。",
      "reason": "体力や筋力を高める文脈で「盛り上がる」は共起せず、「鍛える」「高める」「つける」などを使うのが適切である。"
    }
  ],
  "spot_incorrect": {
    "sentence": "彼らは夜遅くまで映画の感想について熱く盛り上げた。",
    "error_description": "話者たちが自ら熱中して活気づいた文脈であるため、他動詞の「盛り上げた」ではなく自動詞の「盛り上がった」を用いるのが正しい。",
    "corrected": "彼らは夜遅くまで映画の感想について熱く盛り上がった。"
  },
  "word_family_forms": [
    {
      "form": "盛り上がり",
      "pos": "名詞"
    },
    {
      "form": "盛り上げる",
      "pos": "動詞（他動詞）"
    }
  ],
  "word_family_fake_forms": [
    "盛り上がり性",
    "盛り上がり的",
    "盛り上がらし"
  ],
  "syn_ant_candidates": [
    {
      "word": "白熱する",
      "relation": "synonym"
    },
    {
      "word": "活気づく",
      "relation": "synonym"
    },
    {
      "word": "白ける",
      "relation": "antonym"
    },
    {
      "word": "冷める",
      "relation": "antonym"
    }
  ],
  "particle_candidates": {
    "sentence": "好きなアニメの話［ ］友達と盛り上がる。",
    "options": [
      {
        "particle": "で",
        "is_correct": true,
        "explanation": "会話や議論が活性化する原因・材料・話題を表す助詞として「で」が正しく機能する。"
      },
      {
        "particle": "に",
        "is_correct": false,
        "explanation": "助詞「に」は帰着点や対象を表すが、「話に盛り上がる」という表現は助詞選択として不自然である。"
      },
      {
        "particle": "を",
        "is_correct": false,
        "explanation": "「盛り上がる」は自動詞であるため、話題を他動詞の目的語のように「〜を盛り上がる」と指定することはできない。"
      },
      {
        "particle": "から",
        "is_correct": false,
        "explanation": "助詞「から」は起点や根拠を示すため、「話から盛り上がる」とすると話題自体ではなく別の展開へ発展したような不自然な響きになる。"
      }
    ]
  }
}
